from common import *
R = 'f2-backend'
T = []

# ---------------------------------------------------------------- 354 poison messages and DLQs
T.append(topic(354, 'poison-messages-and-dead-letter-queues', R, 24, 'Poison Messages and Dead-Letter Queues',
 ['Recognise a poison message that fails on every attempt',
  'Bound retries and move failing messages to a dead-letter queue',
  'Operate the dead-letter queue: alert, inspect, fix and redrive'],
 2, 11, [227],
 [text(354, 1, 'One bad message can stop a queue',
   'A consumer takes a message, fails on it, and the broker redelivers it. If the failure is in the message itself, such as a malformed field or a reference to a deleted record, every attempt fails the same way. In an ordered queue or partition, the messages behind it wait forever.',
   ['poison-message']),
  text(354, 2, 'Worked example: five tries, then park it',
   'A consumer retries a failing message with backoff of 1, 2, 4 and 8 seconds between five attempts, a total wait of 1 + 2 + 4 + 8 = 15 seconds. After the fifth failure it moves the message to a dead-letter queue and carries on with the next one. An alert fires, an engineer finds a missing field, fixes the producer, and replays the parked message.',
   ['retry-limit', 'dlq']),
  diagram(354, 3, 'Where failing messages go', 'Transient failures are retried; persistent ones are parked, not dropped.', ['dlq'],
   ['Consumer receives the message and tries to process it', 'On failure, retry with backoff while the attempt count is under the limit', 'At the limit, move the message to the dead-letter queue with the error', 'Alert on dead-letter queue depth', 'After a fix, redrive the messages back to the main queue']),
  text(354, 4, 'Transient or permanent?',
   'A timeout to a database is transient and worth retrying. A validation error will fail on every attempt. Classify errors where you can: send permanent failures to the dead-letter queue at once, and give transient ones a few spaced retries so a brief outage does not fill the dead-letter queue.',
   ['retry-limit']),
  text(354, 5, 'Trap: a dead-letter queue nobody watches',
   'Parking messages hides the failure from the main flow. Without an alert on its depth and a way to replay, the dead-letter queue becomes a place where orders and payments silently disappear. Treat a growing dead-letter queue as an incident.',
   ['dlq'])],
 [mc('t354-a1', 'poison-message', 'A message fails with “missing field: customer_id” on every attempt. What is it?',
   [('a', 'A transient failure that more retries will clear'), ('b', 'A poison message that will never succeed as is'), ('c', 'A duplicate that the consumer already handled'), ('d', 'A message that arrived out of order')], 'b',
   'The failure is in the content, so retrying cannot change the outcome.'),
  mc('t354-a2', 'retry-limit', 'Why cap the number of delivery attempts?',
   [('a', 'So one failing message cannot block the queue or burn capacity'), ('b', 'Because brokers delete any message after three failed deliveries'), ('c', 'To turn at-least-once delivery into exactly-once'), ('d', 'To keep the consumer’s memory use constant')], 'a',
   'Unbounded retries turn one bad message into an outage for everything behind it.'),
  mc('t354-a3', 'dlq', 'The consumer has tried a message five times and it still fails. Where should it go next?',
   [('a', 'Delete it so the queue keeps moving'), ('b', 'Put it back at the head of the queue for another try'), ('c', 'Retry it every second until it works'), ('d', 'Move it with its error to a dead-letter queue')], 'd',
   'Parking keeps the data for inspection and replay without blocking the flow.'),
  mc('t354-a4', 'dlq', 'After a producer bug is fixed, 3,000 orders sit in the dead-letter queue. What is the safe next step?',
   [('a', 'Delete them, since they are old'), ('b', 'Redrive them to the main queue with idempotent consumers'), ('c', 'Apply them by hand with SQL updates in the orders database'), ('d', 'Leave them as a record of the incident')], 'b',
   'Replaying through the normal path is safe when consumers ignore duplicates.'),
  order('t354-a5', 'dlq', 'Order the handling of a message that keeps failing.',
   ['Retry with backoff up to the limit', 'Move it to the dead-letter queue with the error', 'Alert on the dead-letter queue depth', 'Fix the cause and redrive'],
   ['s2', 's4', 's1', 's3'], 'Bound the retries, park it, make it visible, then replay after the fix.'),
  est('t354-a6', 'retry-limit', 'A consumer waits 1, 2, 4 and 8 seconds between five attempts. How many seconds pass between the first attempt and the move to the dead-letter queue, ignoring processing time?', 's', 15,
   ['Waits double each time', 'Processing time is negligible'], '1 + 2 + 4 + 8', '1 + 2 + 4 + 8 = 15 s',
   'Sanity check: the backoff should be long enough to outlast a short outage of a dependency, or transient failures land in the dead-letter queue too.', 0, [16, 31])],
 flash(354, [('Poison message?', 'A message that fails on every attempt because of its content.'),
             ('Dead-letter queue?', 'Where messages go after the retry limit, with the error, for inspection and replay.'),
             ('Redrive safely?', 'Fix the cause, replay through the normal path, keep consumers idempotent.')]),
 src([('Amazon SQS: Dead-letter queues', 'https://docs.aws.amazon.com/AWSSimpleQueueService/latest/SQSDeveloperGuide/sqs-dead-letter-queues.html'),
      ('Google Cloud Pub/Sub: Dead-letter topics', 'https://cloud.google.com/pubsub/docs/handling-failures')]),
 deep(['poison-message', 'retry-limit', 'dlq'], 'How retries, limits and dead-letter queues fit together',
  ['Message brokers deliver at least once. If a consumer fails or crashes before acknowledging, the broker delivers the message again. That is what makes queues reliable for transient failures, and it is also why a message that can never succeed keeps coming back.',
   'In a strictly ordered stream, such as a partition consumed in order, the consumer cannot skip a message without giving up ordering. A poison message at the head stops the partition. In an unordered queue, it is redelivered among the others and keeps using consumer time on every attempt.',
   'A retry limit counts deliveries per message. Many brokers track a receive count and move the message to a configured dead-letter queue when it passes the maximum. Consumers can also classify errors: validation failures go straight to the dead-letter queue, while timeouts get retries with exponential backoff and jitter.',
   'The dead-letter queue keeps the original message and, ideally, the error, the attempt count and the consumer version. Operators alert on its depth or age, inspect a sample, fix the producer or the consumer, and then redrive: move the messages back to the source queue to be processed normally.',
   'Redrive delivers messages again, possibly long after they were first sent. Consumers must be idempotent, and handlers should check that the action still makes sense, for example that an order has not been cancelled since. For ordered streams, a parked message can leave later messages for the same entity applied before it, so some systems park the whole entity’s messages together.'],
  ['Any queue or stream consumer whose input can be malformed or refer to missing data.', 'Pipelines where losing a message is worse than delaying it.'],
  ['Avoid infinite redelivery with no limit.', 'Avoid a dead-letter queue with no alert, owner or replay path.'],
  ['Choice', 'Benefit', 'Risk'],
  [['Low retry limit', 'Poison messages leave fast', 'Short outages fill the dead-letter queue'],
   ['High retry limit', 'Rides out longer outages', 'A poison message blocks or burns capacity longer'],
   ['Classify errors first', 'Permanent failures skip retries', 'Misclassified errors are parked or retried wrongly']],
  'How long a message takes to reach the dead-letter queue',
  ['5 attempts', 'Backoff doubles from 1 s', 'Processing time ignored'],
  ['Waits between attempts: 1, 2, 4 and 8 s.', 'Total: 1 + 2 + 4 + 8 = 15 s from first attempt to parking.', 'A dependency outage of 10 s is ridden out; one of 60 s is not.', 'Adding jitter spreads the retries of many messages so they do not arrive together.'],
  'The retry schedule decides which outages are absorbed; anything longer belongs in the dead-letter queue, with an alert.',
  'How managed queues describe it', 'Official documentation',
  'The Amazon SQS developer guide describes a redrive policy that moves a message to a dead-letter queue after it has been received a configured maximum number of times, and a redrive feature to move messages back after the cause is fixed. Google Cloud Pub/Sub documents dead-letter topics that receive messages after a maximum number of delivery attempts.',
  [('“We retry until it works.”', '“I’d cap attempts, park failures with the error, and alert on the dead-letter queue.”'),
   ('“Messages in the dead-letter queue are lost anyway.”', '“They are parked for replay; after the fix I’d redrive them through idempotent consumers.”')],
  ['At-least-once delivery redelivers failures, including poison messages.', 'Bound retries with backoff; park the rest in a dead-letter queue.', 'Alert on dead-letter depth and own the replay.', 'Redrive only into idempotent consumers.']),
 {"kind": "predict", "title": "The stuck partition", "prompt": "An ordered consumer of a payments stream hits a message whose amount field is text, not a number. It retries forever. What happens to the other payments in that partition?",
  "choices": [{"id": "a", "label": "They wait behind it until the message is removed", "feedback": "Right: in-order consumption cannot pass the head, so the whole partition stalls."},
              {"id": "b", "label": "The broker skips the bad message after a while", "feedback": "Brokers redeliver until acknowledged; only a configured limit or the consumer moves it aside."},
              {"id": "c", "label": "Other consumers pick them up in parallel", "feedback": "A partition is consumed in order by one consumer at a time in a group; others do not jump ahead."}],
  "correctId": "a",
  "reveal": "Bound the attempts and move the message to a dead-letter queue with its error, then alert. Because this is a payments stream, decide whether later payments for the same account should wait with it to keep their order."},
 see([(36, 'Queues, acknowledgements and redelivery'), (227, 'Background jobs and how workers retry them')])))

# ---------------------------------------------------------------- 355 clocks
T.append(topic(355, 'clocks-time-and-ordering-in-services', R, 25, 'Clocks, Time and Ordering in Services',
 ['Tell wall-clock time from monotonic time and use each correctly',
  'Explain how clock skew breaks last-write-wins and ordering by timestamp',
  'Order events with versions or sequence numbers instead'],
 3, 12, [221],
 [text(355, 1, 'Two clocks on every machine',
   'A wall clock tells the date and time and can be adjusted: time synchronisation may step it forward or back. A monotonic clock only ever moves forward and is meant for measuring durations. Use the monotonic clock for timeouts and latency, and wall time only to record when something happened.',
   ['wall-vs-monotonic']),
  text(355, 2, 'Worked example: a 300 ms skew loses a write',
   'Server A’s clock runs 300 ms fast. A user saves a profile through A at a true time of 10:00:00.000, stamped 10:00:00.300. They save again 200 ms later through B, stamped 10:00:00.200. Last-write-wins keeps the larger timestamp, so the older save from A wins and the newer one is silently lost.',
   ['clock-skew', 'lww']),
  diagram(355, 3, 'Ordering without trusting clocks', 'Give the order a single source or carry it in the data.', ['ordering'],
   ['Let one writer per item assign increasing version numbers', 'Or let the database assign a sequence at commit', 'Send the version with each update; reject stale ones', 'Use logical clocks when many writers must agree on causality', 'Keep wall time for display and logs only']),
  text(355, 4, 'Skew is normal, not an error',
   'Synchronised clocks on servers in one data centre often agree within a few milliseconds, but drift, pauses and misconfiguration can push skew much higher, and phones can be off by minutes. Any design that compares timestamps from different machines must state how much skew it tolerates.',
   ['clock-skew']),
  text(355, 5, 'Trap: measuring a timeout with wall time',
   'If a timeout is computed as “now minus start” with the wall clock and the clock steps back 2 seconds, the elapsed time can go negative and the timeout never fires; a step forward fires it early. Durations belong to the monotonic clock.',
   ['wall-vs-monotonic'])],
 [mc('t355-a1', 'wall-vs-monotonic', 'Which clock should measure how long a request took?',
   [('a', 'The wall clock, since it shows the real time'), ('b', 'The client’s clock, sent in the request'), ('c', 'The database server’s wall clock'), ('d', 'The monotonic clock, which never steps back')], 'd',
   'Durations need a clock that cannot jump when time is corrected.'),
  mc('t355-a2', 'lww', 'Two servers stamp writes with their own clocks and the larger timestamp wins. What can go wrong?',
   [('a', 'An older write from a fast clock overwrites a newer one'), ('b', 'Both writes are kept side by side as two conflicting copies'), ('c', 'The database refuses writes with equal timestamps'), ('d', 'Reads return the two writes in random order')], 'a',
   'Timestamps from skewed clocks do not reflect real order.'),
  mc('t355-a3', 'ordering', 'How can a service apply updates to one document in the right order?',
   [('a', 'Sort updates by the client device’s timestamp'), ('b', 'Use a version number assigned by one writer or the database'), ('c', 'Apply whichever update arrives last over the network'), ('d', 'Round each timestamp to the nearest second so skew is hidden')], 'b',
   'A single source of versions gives an order that does not depend on clocks.'),
  mc('t355-a4', 'clock-skew', 'A lease holder thinks its 10 s lease has 1 s left; the lock service’s clock says it expired. What is the safe design?',
   [('a', 'Trust the holder, since it took the lease'), ('b', 'Extend each lease to 60 s so it cannot expire mid-write'), ('c', 'Use a fencing token the storage checks on every write'), ('d', 'Synchronise clocks before each write')], 'c',
   'Fencing tokens let the storage reject writes from a holder whose lease has passed, whatever its clock says.'),
  order('t355-a5', 'ordering', 'Order a versioned update that cannot apply out of order.',
   ['Read the document and its version', 'Change it locally', 'Write only if the version is unchanged', 'On a mismatch, re-read and retry or report'],
   ['s4', 's2', 's1', 's3'], 'The version, not a timestamp, decides whether the write is still based on the latest state.'),
  est('t355-a6', 'clock-skew', 'Server A’s clock is 300 ms ahead of server B’s. With last-write-wins on timestamps, for how many milliseconds after a write on A can a real later write on B still lose?', 'ms', 300,
   ['Both writes target the same key', 'Network delays ignored'], 'skew = 300 ms', 'Any write on B less than 300 ms after a write on A gets a smaller timestamp and loses',
   'Sanity check: the loss window equals the skew, so it grows with worse synchronisation.', 0, [150, 600])],
 flash(355, [('Wall vs monotonic clock?', 'Wall: date and time, can step. Monotonic: only forward, for durations.'),
             ('Why does LWW lose writes?', 'With skew, an older write can carry a larger timestamp.'),
             ('Order without clocks?', 'Versions from one writer or the database, or logical clocks.')]),
 src([('Linux man-pages: clock_gettime(2)', 'https://man7.org/linux/man-pages/man2/clock_gettime.2.html'),
      ('RFC 5905: Network Time Protocol Version 4', 'https://www.rfc-editor.org/rfc/rfc5905')]),
 deep(['wall-vs-monotonic', 'clock-skew', 'lww', 'ordering'], 'Why timestamps from different machines do not order events',
  ['Every machine keeps time with a local oscillator that drifts. Time synchronisation, such as NTP, measures the offset to reference servers and corrects it, either by slewing the clock gradually or by stepping it when the offset is large. Between corrections, clocks on different machines disagree by some amount: the skew.',
   'Operating systems expose at least two clocks. The real-time clock follows the synchronised wall time and can jump. The monotonic clock counts from an arbitrary start, never goes backwards and is not stepped by time corrections. Timeouts, rate limits and latency measurements should use the monotonic clock.',
   'Last-write-wins resolves conflicting writes by keeping the one with the largest timestamp. When timestamps come from different machines, the order they give is only as good as the skew. A write can lose to one that really happened earlier, and nothing reports the loss.',
   'To order updates to one item, let a single authority assign the order: the item’s owner service, a primary database that assigns a sequence or commit order, or a version column checked on every write. Clients send the version they read; a stale version is rejected instead of overwriting newer data.',
   'When many writers must agree on what caused what, logical clocks help. A Lamport clock gives an order consistent with causality; vector clocks can also detect concurrent writes so they can be merged or shown to a user. Some databases combine bounded clock uncertainty with waiting out that bound, which needs carefully engineered time sources.'],
  ['Any service that times work, expires leases or resolves concurrent writes.', 'Logs and traces that must line up across machines, with skew in mind.'],
  ['Avoid last-write-wins on wall-clock timestamps from different machines for data that matters.', 'Avoid wall time for timeouts and elapsed-time checks.'],
  ['Ordering method', 'Needs', 'Weakness'],
  [['Wall-clock timestamps', 'Synchronised clocks', 'Skew reorders and loses writes'],
   ['Version per item', 'One authority per item', 'Contention on hot items'],
   ['Logical clocks', 'Metadata on every message', 'No link to real time']],
  'How skew turns into lost writes',
  ['Server A runs 300 ms fast', 'A user saves through A, then 200 ms later through B', 'Last-write-wins on timestamps'],
  ['A’s write: true 10:00:00.000, stamped 10:00:00.300.', 'B’s write: true 10:00:00.200, stamped 10:00:00.200.', 'LWW keeps A’s write because 0.300 > 0.200, so the user’s newer change is lost.', 'Any write on B within 300 ms after a write on A loses the same way.'],
  'The loss window equals the skew. Versions remove it; better synchronisation only shrinks it.',
  'What the specifications say', 'Official documentation',
  'The Linux manual page for the clock functions describes a realtime clock that can be set and can jump, and a monotonic clock that cannot be set and is not affected by discontinuous jumps in system time, though it can be slewed. RFC 5905 specifies NTP version 4, which estimates the offset to time servers and disciplines the local clock, with accuracy depending on network conditions.',
  [('“Our servers use NTP, so timestamps order events.”', '“Skew is small but not zero; I’d order with versions and keep timestamps for display.”'),
   ('“Elapsed time is now minus start.”', '“With the monotonic clock, so a time correction cannot break the timeout.”')],
  ['Use the monotonic clock for durations and timeouts.', 'Clocks on different machines disagree; state the skew you tolerate.', 'Last-write-wins on wall time can drop newer writes.', 'Order updates with versions, sequences or logical clocks.']),
 {"kind": "predict", "title": "Which save survives?", "prompt": "Server A’s clock is 300 ms fast. A user saves a draft through A, then 200 ms later saves a newer version through B. The store keeps the write with the larger timestamp. Which version is stored?",
  "choices": [{"id": "a", "label": "The newer save through B", "feedback": "B’s timestamp is 10:00:00.200, smaller than A’s 10:00:00.300, so it loses."},
              {"id": "b", "label": "The older save through A", "feedback": "Right: A’s fast clock gives its older write the larger timestamp."},
              {"id": "c", "label": "Both, as conflicting versions", "feedback": "Last-write-wins keeps one value; it does not report conflicts."}],
  "correctId": "b",
  "reveal": "Last-write-wins picks the larger timestamp, not the later event. With a version number checked on each save, B’s save would be based on A’s version and both would apply in order."},
 see([(47, 'Lamport and vector clocks for causal order'), (224, 'Idempotent endpoints that handle repeated writes')])))

# ---------------------------------------------------------------- 356 load shedding
T.append(topic(356, 'load-shedding-and-backpressure', R, 26, 'Load Shedding and Backpressure',
 ['Explain why a queue in front of an overloaded server makes every request late',
  'Shed excess load early with a clear retryable reply',
  'Use bounded queues and backpressure so producers slow down'],
 3, 12, [239],
 [text(356, 1, 'More work than capacity has only three outcomes',
   'When requests arrive faster than a server can finish them, the excess must go somewhere: it waits in a queue, it is rejected, or the sender slows down. Waiting looks kind, but past a point every request waits longer than its caller will, and the server spends all its effort on answers nobody reads.',
   ['overload']),
  text(356, 2, 'Worked example: 1,500 requests per second into 1,000',
   'A server finishes 1,000 requests per second and 1,500 arrive. Without limits, the queue grows by 500 every second: after 60 seconds it holds 30,000 requests, and a new one waits 30 seconds. With a 2-second client timeout, almost everything served is already abandoned. Rejecting the extra 500 per second keeps 1,000 good answers per second flowing.',
   ['overload', 'shedding']),
  diagram(356, 3, 'Shedding at the front door', 'Reject early and cheaply, before work is spent.', ['shedding'],
   ['Measure in-flight requests or queue time', 'Above the limit, reject with 503 and a Retry-After hint', 'Prefer to drop low-priority work first', 'Bound every queue; drop requests already past their deadline', 'Clients back off with jitter instead of retrying at once']),
  text(356, 4, 'Backpressure between stages',
   'Inside a pipeline, a full buffer should slow the stage before it rather than grow without limit. A bounded queue that blocks or refuses new items passes the pressure upstream until it reaches something that can wait, shed or scale, instead of exhausting memory in the middle.',
   ['backpressure']),
  text(356, 5, 'Trap: an unbounded queue “so nothing is lost”',
   'An unbounded queue turns a short overload into minutes of latency and can exhaust memory. Requests are not saved; they are delayed past usefulness. Bound the queue and decide explicitly what is rejected.',
   ['overload', 'backpressure'])],
 [mc('t356-a1', 'overload', 'Arrivals exceed capacity by 20% for ten minutes and the queue is unbounded. What happens to latency?',
   [('a', 'It rises by about 20% and stays there'), ('b', 'It stays flat because the queue absorbs the excess'), ('c', 'It keeps growing for as long as the overload lasts'), ('d', 'It falls once the server warms its caches')], 'c',
   'The backlog grows every second the excess lasts, and every new request waits behind it.'),
  mc('t356-a2', 'shedding', 'What reply suits a request shed because the server is overloaded?',
   [('a', '400 Bad Request, as the client sent too many requests'), ('b', '503 Service Unavailable with a Retry-After hint'), ('c', '200 OK with an empty body'), ('d', '404 Not Found until load falls')], 'b',
   '503 says the failure is temporary and Retry-After tells well-behaved clients when to come back.'),
  mc('t356-a3', 'shedding', 'Why reject at the front door rather than after partial processing?',
   [('a', 'A late rejection gives the client a more detailed error message'), ('b', 'Partial work is usually cached for later'), ('c', 'Clients ignore early rejections'), ('d', 'An early rejection is cheap; a late one wastes capacity')], 'd',
   'Shedding is only useful if dropping a request is much cheaper than serving it.'),
  mc('t356-a4', 'backpressure', 'A parser stage feeds a slower database writer through a buffer. What prevents memory from running out?',
   [('a', 'A bounded buffer that makes the parser wait when full'), ('b', 'A larger in-memory buffer sized for the busiest day of the year'), ('c', 'Writing to the database from more threads'), ('d', 'Compressing items in the buffer')], 'a',
   'Bounding the buffer pushes the slowdown upstream instead of piling items in memory.'),
  order('t356-a5', 'shedding', 'Order what a server does with a request during overload.',
   ['Check in-flight count against the limit', 'Reject cheaply with 503 and Retry-After if over', 'Otherwise check the request’s deadline', 'Process it if there is still time'],
   ['s2', 's4', 's1', 's3'], 'Decide cheaply first, then avoid work whose caller has already given up.'),
  est('t356-a6', 'overload', '1,500 requests per second arrive at a server that finishes 1,000 per second. With an unbounded queue, how many requests are waiting after 60 seconds?', 'requests', 30000,
   ['Arrival and service rates are steady', 'The queue starts empty'], '(1,500 − 1,000) × 60', '500 × 60 = 30,000 requests',
   'Sanity check: at 1,000 per second that backlog takes 30 s to clear, far past a 2 s timeout.', 0.05, [90000, 500])],
 flash(356, [('Overload outcomes?', 'Queue, reject, or slow the sender; queues alone make everyone late.'),
             ('Good shed reply?', '503 with Retry-After, returned before work is spent.'),
             ('Backpressure?', 'A full bounded buffer slows the stage before it.')]),
 src([('Google SRE book: Handling Overload', 'https://sre.google/sre-book/handling-overload/'),
      ('RFC 9110: HTTP Semantics (503 and Retry-After)', 'https://www.rfc-editor.org/rfc/rfc9110')]),
 deep(['overload', 'shedding', 'backpressure'], 'Why queues fail under sustained overload',
  ['A server has a maximum throughput. When the arrival rate is below it, queues stay short and absorb bursts. When arrivals exceed it for long, the queue grows by the difference every second, and the waiting time for each new request grows with it. Little’s law ties them together: items in the system equal arrival rate times time in the system.',
   'Callers have timeouts. Once the queue wait passes the timeout, the server finishes requests whose callers have gone, and it may receive retries for them on top. Throughput of useful answers falls towards zero even though the server is fully busy. This is congestion collapse.',
   'Load shedding caps the work admitted. A server tracks in-flight requests, queue time or CPU, and above a limit rejects new requests quickly with 503 and, where sensible, Retry-After. Rejection must be far cheaper than serving, so it happens before authentication-heavy or database work where possible.',
   'Not all requests are equal. Shedding can drop background, batch or retry traffic first and keep interactive requests. Requests already past their deadline should be dropped when dequeued. Clients must cooperate: limited retries, exponential backoff with jitter, and respect for Retry-After, or shed requests come straight back.',
   'Backpressure is the same idea inside a system. A bounded queue between stages blocks or refuses when full, so a slow consumer slows its producer rather than letting memory grow. Pressure moves upstream until it reaches a point that can wait, shed or scale, such as the edge of the system or an autoscaler.'],
  ['Any service that can receive more traffic than it can serve, which is every public service.', 'Pipelines whose stages run at different speeds.'],
  ['Avoid unbounded queues and thread pools in request paths.', 'Avoid client retries without backoff, jitter and a limit.'],
  ['Response to overload', 'Effect on latency', 'Effect on useful work'],
  [['Unbounded queue', 'Grows without limit', 'Falls towards zero after timeouts'],
   ['Shed excess at the front', 'Stays low for admitted work', 'Stays near capacity'],
   ['Backpressure to the source', 'Moves waiting upstream', 'Preserved if the source can wait']],
  'The cost of queueing an overload',
  ['Capacity 1,000 requests/s; arrivals 1,500/s for 60 s', 'Clients time out after 2 s'],
  ['Excess: 1,500 − 1,000 = 500 per second.', 'Queue after 60 s: 500 × 60 = 30,000 requests.', 'A new request waits 30,000 ÷ 1,000 = 30 s, fifteen times the timeout.', 'Shedding 500/s instead keeps waits near zero and 1,000 useful answers per second.'],
  'Shedding a third of the traffic keeps two thirds succeeding; queueing all of it lets nearly all of it fail.',
  'What the Google SRE book recommends', 'Official documentation',
  'The Google SRE book’s chapter on handling overload describes servers protecting themselves by rejecting requests they cannot serve in time, client-side throttling that stops sending requests likely to be rejected, request criticality so the least important traffic is dropped first, and retry budgets that keep retries from multiplying load during an overload.',
  [('“We queue everything so no request is lost.”', '“Past the timeout the queue only delays failures; I’d bound it and shed early with 503.”'),
   ('“Clients should retry immediately on 503.”', '“With backoff, jitter and Retry-After, or the retries become the overload.”')],
  ['Sustained overload grows queues and latency without limit.', 'Shed early and cheaply with 503 and Retry-After.', 'Drop low-priority and expired work first.', 'Bound queues so backpressure reaches the source.']),
 {"kind": "slider", "title": "Queue it or shed it?", "prompt": "A server finishes 1,000 requests per second and clients time out after 2 s. Slide the arrival rate and compare a server that queues everything with one that sheds the excess, after 60 seconds.",
  "model": "load-shed", "params": {"capacity": 1000, "timeoutS": 2, "seconds": 60},
  "control": {"label": "Arrivals", "min": 500, "max": 2000, "step": 10, "initial": 1500, "unit": "/s"},
  "takeaway": "Even 3% over capacity, at 1,030 per second, builds a 1.8 s wait in a minute; at 1,500 the wait is 30 s and nothing useful comes out. Shedding the excess keeps up to 1,000 good answers per second however high arrivals go."},
 see([(53, 'Timeouts, retries and circuit breakers that pair with shedding'), (233, 'Rate limiting, which caps load per client')])))
